-- | Neurális számítások tiszta funkcionális implementáció
class NeuralComputation m where
  forwardPass :: Vector Double -> m (Vector Double)
  backwardPass :: Vector Double -> m (Vector (Vector Double))
  updateWeights :: Vector (Vector Double) -> m ()

instance NeuralComputation JAIDE where
  forwardPass input = do
    state <- get
    let networkState = jsNetworkState state
    let weights = nsWeights networkState
    let biases = nsBiases networkState

    -- Mátrix szorzás párhuzamosítva
    let result = V.zipWith (+) biases $ V.map (dotProduct input) weights
    let activated = V.map sigmoid result

    return activated
    where
      dotProduct v1 v2 = V.sum $ V.zipWith (*) v1 v2
      sigmoid x = 1 / (1 + exp (-x))

  backwardPass gradients = do
    state <- get
    let networkState = jsNetworkState state
    let weights = nsWeights networkState

    -- Gradiens számítás párhuzmosan
    let weightGradients = parMap rpar (V.map (* head (V.toList gradients))) weights

    return weightGradients

  updateWeights newGradients = do
    state <- get
    let networkState = jsNetworkState state
    let oldWeights = nsWeights networkState
    let optimizer = nsOptimizer networkState

    -- Adam optimalizáció
    let AdamState{..} = optimizer
    let newMomentum = V.zipWith3 adamMomentum asMomentum oldWeights newGradients
    let newVelocity = V.zipWith3 adamVelocity asVelocity oldWeights newGradients
    let updatedWeights = V.zipWith3 adamUpdate oldWeights newMomentum newVelocity

    let newOptimizer = optimizer { asMomentum = newMomentum, asVelocity = newVelocity }
    let newNetworkState = networkState { nsWeights = updatedWeights, nsOptimizer = newOptimizer }

    put $ state { jsNetworkState = newNetworkState }

    where
      adamMomentum momentum weight gradient = V.zipWith (+) 
        (V.map (* 0.9) momentum) 
        (V.map (* 0.1) gradient)
      adamVelocity velocity weight gradient = V.zipWith (+)
        (V.map (* 0.999) velocity)
        (V.map (* 0.001 . (**2)) gradient)
      adamUpdate weight momentum velocity = V.zipWith3 (\w m v -> w - 0.001 * m / (sqrt v + 1e-8)) weight momentum velocity

-- | Kvantum számítások
class QuantumComputation m where
  evolveQuantumState :: Vector Double -> m QuantumState
  measureObservables :: QuantumState -> m (Vector Double)
  entangleStates :: QuantumState -> QuantumState -> m QuantumState

instance QuantumComputation JAIDE where
  evolveQuantumState neuralInput = do
    state <- get
    let quantumState = jsQuantumState state
    let amplitudes = qsAmplitudes quantumState
    let phases = qsPhases quantumState

    -- Kvantum evolúció Hamiltonian alapján
    let evolvedAmplitudes = V.zipWith3 evolveAmplitude amplitudes phases neuralInput
    let normalizedAmplitudes = normalizeQuantumState evolvedAmplitudes

    let newQuantumState = quantumState { qsAmplitudes = normalizedAmplitudes }
    put $ state { jsQuantumState = newQuantumState }

    return newQuantumState
    where
      evolveAmplitude (Complex re im) phase neuralMod = 
        let newPhase = phase + neuralMod * 0.1
        in Complex (re * cos newPhase - im * sin newPhase) (re * sin newPhase + im * cos newPhase)

      normalizeQuantumState amps = 
        let norm = sqrt $ V.sum $ V.map (\(Complex re im) -> re*re + im*im) amps
        in V.map (\(Complex re im) -> Complex (re/norm) (im/norm)) amps

  measureObservables quantumState = do
    let amplitudes = qsAmplitudes quantumState
    let probabilities = V.map (\(Complex re im) -> re*re + im*im) amplitudes

    -- Observable mérések
    let observables = V.map measureSingle probabilities
    return observables
    where
      measureSingle prob = if prob > 0.5 then 1.0 else 0.0

  entangleStates state1 state2 = do
    let amps1 = qsAmplitudes state1
    let amps2 = qsAmplitudes state2
    let entangled = V.zipWith tensorProduct amps1 amps2

    return $ state1 { qsAmplitudes = entangled }
    where
      tensorProduct (Complex a b) (Complex c d) = Complex (a*c - b*d) (a*d + b*c)

