  return [TrainingBatch (V.replicate 2048 0.5) (V.replicate 2048 0.7)]

computeLoss :: Vector Double -> Vector Double -> Double
computeLoss predicted target = 
  let differences = V.zipWith (-) predicted target
      squaredDiffs = V.map (**2) differences
  in V.sum squaredDiffs / fromIntegral (V.length predicted)

